function PlenaPreview({onExit}:{onExit:()=>void}) {
  const [sampleOpen,setSampleOpen]=useState(false);
  const [lockedOpen,setLockedOpen]=useState(false);
  const whatsapp="https://wa.me/5519989241139?text=Ol%C3%A1%2C%20conheci%20a%20demonstra%C3%A7%C3%A3o%20do%20Programa%20Plena%20Mulher%20e%20gostaria%20de%20agendar%20uma%20consulta.";
  return <main className="plena-app-shell">
    <aside className="plena-sidebar"><button className="brand plena-sidebar-brand" onClick={onExit}><span className="brand-mark">C</span><span><strong>Dra. Camila</strong><small>Plena Mulher</small></span></button><nav><button className="nav-button active"><span>⌂</span>Visão geral</button><p className="nav-label">Cadernos da jornada</p>{plenaNotebooks.map(x=><button className={`nav-button ${x.available?"assigned":""}`} key={x.n} onClick={()=>x.available?setSampleOpen(true):setLockedOpen(true)}><span>{x.n}</span>{x.title}</button>)}</nav><div className="sidebar-foot"><p>Quer saber mais?</p><a href={whatsapp} target="_blank" rel="noreferrer">Falar com a equipe</a></div></aside>
    <section className="plena-workspace"><header className="workspace-head"><div><p className="eyebrow">Demonstração do programa</p><h1>Plena Mulher</h1></div><button className="plena-exit" onClick={onExit}>← Voltar aos programas</button></header>
      <section className="plena-dashboard-hero"><div><span>Saúde da mulher</span><h2>Seu corpo muda.<br/>Seu cuidado também pode evoluir.</h2><p>Conheça uma experiência de acompanhamento pensada para organizar sintomas, prioridades e decisões na transição menopausal e na pós-menopausa.</p></div><a href={whatsapp} target="_blank" rel="noreferrer">Quero agendar uma consulta →</a></section>
      <section className="plena-dashboard-intro"><div><p className="eyebrow">Cadernos de acompanhamento</p><h2>Veja o que pode fazer parte da sua jornada</h2></div><p>1 amostra disponível · 6 conteúdos personalizados</p></section>
      <div className="plena-module-grid">{plenaNotebooks.map(x=><article className={`plena-module-card ${x.available?"available":"locked"}`} key={x.n} role="button" tabIndex={0} onClick={()=>x.available?setSampleOpen(true):setLockedOpen(true)} onKeyDown={e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();x.available?setSampleOpen(true):setLockedOpen(true)}}}><div><span>{x.n}</span><b>{x.available?"Amostra disponível":"Conteúdo personalizado"}</b></div><small>{x.tag}</small><h3>{x.title}</h3><p>{x.desc}</p>{!x.available&&<em>◎ Liberado conforme avaliação</em>}<button>{x.available?"Explorar esta amostra →":"Descobrir como funciona →"}</button></article>)}</div>
      <section className="plena-care-note"><span>i</span><div><h3>Uma jornada individualizada</h3><p>Os cadernos são selecionados após avaliação médica. A demonstração é educativa e não define diagnóstico, tratamento ou indicação de terapia hormonal.</p></div></section>
    </section>
    {sampleOpen&&<div className="interest-modal plena-modal" role="dialog" aria-modal="true"><button className="modal-backdrop" aria-label="Fechar" onClick={()=>setSampleOpen(false)}/><section><button className="modal-close" onClick={()=>setSampleOpen(false)} aria-label="Fechar">×</button><span className="modal-kicker">Amostra interativa</span><h2>Ondas de calor e sono</h2><p>Nos últimos dias, com que frequência as ondas de calor interferiram no seu sono ou nas suas atividades?</p><div className="plena-choice-grid">{["Não percebi","Poucas vezes","Alguns dias","Frequentemente"].map(x=><button key={x}>{x}</button>)}</div><label className="plena-question">O que mais gostaria de compreender sobre esse sintoma?<textarea placeholder="Escreva uma dúvida ou percepção..."/></label><a href={whatsapp} target="_blank" rel="noreferrer">Quero conhecer o acompanhamento completo →</a><small>Esta amostra não substitui avaliação médica.</small></section></div>}
    {lockedOpen&&<div className="interest-modal plena-modal" role="dialog" aria-modal="true"><button className="modal-backdrop" aria-label="Fechar" onClick={()=>setLockedOpen(false)}/><section><button className="modal-close" onClick={()=>setLockedOpen(false)} aria-label="Fechar">×</button><span className="modal-kicker">Conteúdo do programa completo</span><h2>Um cuidado que considera o seu momento.</h2><p>Após a consulta, a Dra. Camila seleciona os temas que podem ajudar a organizar seus sintomas, riscos, prioridades e objetivos.</p><div className="modal-preview"><span>✓</span><p><strong>Seleção individualizada</strong><br/>Sem formulários desnecessários ou respostas genéricas.</p></div><a href={whatsapp} target="_blank" rel="noreferrer">Quero conversar com a equipe →</a><small>A avaliação permite definir se o programa é adequado para você.</small></section></div>}
  </main>
}

const diabetesNotebooks = [
  {n:"01",title:"Glicemias e padrões",tag:"Monitorização",desc:"Observe horários, contexto e tendências para levar informações mais claras à consulta.",available:true},
  {n:"02",title:"Alimentação no dia a dia",tag:"Educação alimentar",desc:"Organize refeições, dúvidas e respostas percebidas sem dietas genéricas ou culpa."},
  {n:"03",title:"Medicamentos e insulinoterapia",tag:"Tratamento",desc:"Registre o uso prescrito, dificuldades e dúvidas sem alterar doses por conta própria."},
  {n:"04",title:"Hipoglicemia e segurança",tag:"Segurança",desc:"Reconheça situações que merecem prevenção, orientação e um plano individual de ação."},
  {n:"05",title:"Movimento e resposta glicêmica",tag:"Atividade física",desc:"Perceba como diferentes atividades conversam com energia, rotina e glicose."},
  {n:"06",title:"Exames e prevenção",tag:"Prevenção",desc:"Reúna exames, rastreamentos e prioridades para reduzir riscos ao longo do tempo."},
  {n:"07",title:"Metas e plano de cuidado",tag:"Jornada",desc:"Transforme decisões compartilhadas em próximos passos possíveis e revisáveis."},
];

function DiabetesPreview({onExit}:{onExit:()=>void}) {
  const [sampleOpen,setSampleOpen]=useState(false);
  const [lockedOpen,setLockedOpen]=useState(false);
  const whatsapp="https://wa.me/5519989241139?text=Ol%C3%A1%2C%20conheci%20a%20demonstra%C3%A7%C3%A3o%20do%20Programa%20Viver%20Bem%20com%20Diabetes%20e%20gostaria%20de%20agendar%20uma%20consulta.";
  return <main className="diabetes-app-shell">
    <aside className="diabetes-sidebar"><button className="brand diabetes-sidebar-brand" onClick={onExit}><span className="brand-mark">C</span><span><strong>Dra. Camila</strong><small>Viver Bem com Diabetes</small></span></button><nav><button className="nav-button active"><span>⌂</span>Visão geral</button><p className="nav-label">Cadernos da jornada</p>{diabetesNotebooks.map(x=><button className={`nav-button ${x.available?"assigned":""}`} key={x.n} onClick={()=>x.available?setSampleOpen(true):setLockedOpen(true)}><span>{x.n}</span>{x.title}</button>)}</nav><div className="sidebar-foot"><p>Quer saber mais?</p><a href={whatsapp} target="_blank" rel="noreferrer">Falar com a equipe</a></div></aside>
    <section className="diabetes-workspace"><header className="workspace-head"><div><p className="eyebrow">Demonstração do programa</p><h1>Viver Bem com Diabetes</h1></div><div className="diabetes-head-actions"><a href="https://viver-bem-diabetes-insulina.camimelomatos0.chatgpt.site" target="_blank" rel="noreferrer">Abrir jornada Diabetes + Insulina ↗</a><button className="diabetes-exit" onClick={onExit}>← Voltar aos programas</button></div></header>
      <section className="diabetes-dashboard-hero"><div><span>Glicose, educação e prevenção</span><h2>Mais informação.<br/>Mais segurança.<br/>Mais autonomia.</h2><p>Uma jornada para pessoas com diabetes, pré-diabetes ou resistência à insulina organizarem glicemias, tratamento, rotina e prevenção junto à equipe de saúde.</p></div><a href={whatsapp} target="_blank" rel="noreferrer">Quero agendar uma consulta →</a></section>
      <section className="diabetes-dashboard-intro"><div><p className="eyebrow">Cadernos de acompanhamento</p><h2>Veja o que pode fazer parte da sua jornada</h2></div><p>1 amostra disponível · 6 conteúdos personalizados</p></section>
      <div className="diabetes-module-grid">{diabetesNotebooks.map(x=><article className={`diabetes-module-card ${x.available?"available":"locked"}`} key={x.n} role="button" tabIndex={0} onClick={()=>x.available?setSampleOpen(true):setLockedOpen(true)} onKeyDown={e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();x.available?setSampleOpen(true):setLockedOpen(true)}}}><div><span>{x.n}</span><b>{x.available?"Amostra disponível":"Conteúdo personalizado"}</b></div><small>{x.tag}</small><h3>{x.title}</h3><p>{x.desc}</p>{!x.available&&<em>◎ Liberado conforme avaliação</em>}<button>{x.available?"Explorar esta amostra →":"Descobrir como funciona →"}</button></article>)}</div>
      <section className="diabetes-care-note"><span>i</span><div><h3>Educação para apoiar decisões compartilhadas</h3><p>Os cadernos são selecionados após avaliação médica. A demonstração não define metas glicêmicas, doses, diagnóstico ou tratamento. Não altere medicamentos ou insulina por conta própria.</p></div></section>
    </section>
    {sampleOpen&&<div className="interest-modal diabetes-modal" role="dialog" aria-modal="true"><button className="modal-backdrop" aria-label="Fechar" onClick={()=>setSampleOpen(false)}/><section><button className="modal-close" onClick={()=>setSampleOpen(false)} aria-label="Fechar">×</button><span className="modal-kicker">Amostra interativa</span><h2>Glicemias e padrões</h2><p>Ao observar seus registros, em qual período você percebe maior dificuldade para manter a glicose na faixa combinada com sua equipe?</p><div className="diabetes-choice-grid">{["Ao acordar","Após refeições","Durante atividade física","Não identifico um padrão"].map(x=><button key={x}>{x}</button>)}</div><label className="diabetes-question">Que dúvida você gostaria de levar à consulta?<textarea placeholder="Escreva uma dúvida ou percepção..."/></label><a href={whatsapp} target="_blank" rel="noreferrer">Quero conhecer o acompanhamento completo →</a><small>Esta amostra é educativa e não substitui avaliação médica.</small></section></div>}
    {lockedOpen&&<div className="interest-modal diabetes-modal" role="dialog" aria-modal="true"><button className="modal-backdrop" aria-label="Fechar" onClick={()=>setLockedOpen(false)}/><section><button className="modal-close" onClick={()=>setLockedOpen(false)} aria-label="Fechar">×</button><span className="modal-kicker">Conteúdo do programa completo</span><h2>Um plano que respeita sua rotina e seu tratamento.</h2><p>Após a consulta, a Dra. Camila seleciona os temas que podem ajudar a organizar glicemias, dúvidas, segurança e prevenção conforme sua avaliação.</p><div className="modal-preview"><span>✓</span><p><strong>Seleção individualizada</strong><br/>Conteúdos alinhados ao seu diagnóstico, tratamento e objetivos.</p></div><a href={whatsapp} target="_blank" rel="noreferrer">Quero conversar com a equipe →</a><small>A avaliação permite definir se o programa é adequado para você.</small></section></div>}
  </main>
}

function Sidebar({active,onHome,onOpen,onExit}:{current:string|null;active:string[];onHome:()=>void;onOpen:(id:string)=>void;onExit:()=>void}) { return <aside className="sidebar"><button className="brand sidebar-brand" onClick={onExit}><span className="brand-mark">C</span><span><strong>Dra. Camila</strong><small>Equilíbrio Metabólico</small></span></button><nav><button className="nav-button active" onClick={onHome}><span>⌂</span>Painel geral</button><p className="nav-label">Todos os cadernos</p>{modules.map(m=><button className={`nav-button ${active.includes(m.id)?"assigned":""}`} key={m.id} onClick={()=>onOpen(m.id)}><span>{m.n}</span>{m.title}</button>)}</nav><div className="sidebar-foot"><p>Precisa de ajuda?</p><a href="https://wa.me/5519989241139">Falar com a equipe</a></div></aside> }

function ModuleView({module,value,tab,setTab,onBack,onChange,patient,nextVisit}:{module:ModuleConfig;value:ModuleData;tab:string;setTab:(v:string)=>void;onBack:()=>void;onChange:(fn:(old:ModuleData)=>ModuleData)=>void;patient:string;nextVisit:string}) {
  const addEntry=()=>onChange(old=>({...old,entries:[...(old.entries||[]),{}]}));
  const setEntry=(index:number,key:string,val:string|number)=>onChange(old=>({...old,entries:old.entries.map((e,i)=>i===index?{...e,[key]:val}:e)}));
  const scaleFields=module.entryFields.filter(f=>f.scale);
  const scored=value.entries.filter(hasContent).map((entry,i)=>({label:`Registro ${i+1}`,score:scaleFields.length?Math.round(scaleFields.reduce((s,f)=>s+Number(entry[f.key]||0),0)/scaleFields.length):0}));
  return <main className="notebook-shell"><header className="notebook-header"><button className="back-button" onClick={onBack}>← Painel</button><div className="notebook-brand"><span>{module.n}</span><div><small>Equilíbrio Metabólico</small><strong>{module.title}</strong></div></div><div className="patient-mini"><span>{patient||"Paciente"}</span><small>{nextVisit?`Consulta ${new Date(`${nextVisit}T12:00:00`).toLocaleDateString("pt-BR")}`:"Consulta a definir"}</small></div></header><div className="notebook-tabs" role="tablist">{[["inicio","Ponto de partida"],["registros","Registros"],["sintese","Síntese e gráfico"],["consulta","Para a consulta"]].map(([id,label])=><button role="tab" aria-selected={tab===id} className={tab===id?"active":""} key={id} onClick={()=>setTab(id)}>{label}</button>)}</div><section className="notebook-content"><div className="notebook-title"><p className="eyebrow">{module.tag}</p><h1>{module.title}</h1><p>{module.subtitle}</p></div>
    {tab==="inicio"&&<div className="form-layout"><div className="form-main"><section className="paper-card"><div className="paper-heading"><span>01</span><div><h2>O que percebo hoje</h2><p>Marque somente o que fizer sentido neste momento.</p></div></div><div className="check-grid">{module.checks.map(item=><label className={value.checks.includes(item)?"checked":""} key={item}><input type="checkbox" checked={value.checks.includes(item)} onChange={()=>onChange(old=>({...old,checks:old.checks.includes(item)?old.checks.filter(x=>x!==item):[...old.checks,item]}))}/><span>✓</span>{item}</label>)}</div></section><section className="paper-card"><div className="paper-heading"><span>02</span><div><h2>Sobre este momento</h2><p>Escreva com suas palavras. Não há resposta certa.</p></div></div>{module.startFields.map((label,i)=><label className="text-field" key={label}>{label}<textarea value={value.start[i]||""} onChange={e=>onChange(old=>({...old,start:old.start.map((v,j)=>j===i?e.target.value:v)}))} placeholder="Escreva aqui..."/></label>)}</section></div><aside className="form-aside"><div className="guidance"><span>Como usar</span><h3>Observe sem transformar o registro em obrigação.</h3><ul><li>Escolha poucos momentos.</li><li>Descreva fatos sem culpa.</li><li>Não mude o tratamento.</li><li>Pare se o registro fizer mal.</li></ul></div><div className="limit-note"><strong>Limite deste caderno</strong><p>{module.limit}</p></div></aside></div>}
    {tab==="registros"&&<div><div className="records-intro"><div><h2>{module.entryTitle}</h2><p>Registre apenas situações escolhidas. Você pode voltar e editar depois.</p></div><button className="primary-button" onClick={addEntry}>+ Novo registro</button></div>{value.entries.length===0?<button className="empty-records" onClick={addEntry}><span>＋</span><strong>Começar meu primeiro registro</strong><small>Leva cerca de dois minutos</small></button>:<div className="records-list">{value.entries.map((entry,index)=><article className="record-card" key={index}><div className="record-number"><span>{String(index+1).padStart(2,"0")}</span><button onClick={()=>onChange(old=>({...old,entries:old.entries.filter((_,i)=>i!==index)}))}>Remover</button></div><div className="record-fields">{module.entryFields.map(field=><label className={`text-field ${field.scale?"wide":""}`} key={field.key}>{field.label}{field.scale?<Scale value={Number(entry[field.key]??-1)} onChange={v=>setEntry(index,field.key,v)}/>:<textarea rows={2} value={String(entry[field.key]||"")} onChange={e=>setEntry(index,field.key,e.target.value)} placeholder="Escreva aqui..."/>}</label>)}</div></article>)}</div>}</div>}
    {tab==="sintese"&&<div className="insight-layout"><section className="paper-card"><div className="paper-heading"><span>03</span><div><h2>O que percebi</h2><p>Procure tendências, não respostas perfeitas.</p></div></div>{module.insights.map((label,i)=><label className="text-field" key={label}>{label}<textarea value={value.insights[i]||""} onChange={e=>onChange(old=>({...old,insights:old.insights.map((v,j)=>j===i?e.target.value:v)}))} placeholder="Minha percepção..."/></label>)}<label className="text-field priority-field">Uma prioridade possível para a próxima semana<input value={value.priority} onChange={e=>onChange(old=>({...old,priority:e.target.value}))} placeholder="Pequena, concreta e possível"/></label></section><section className="chart-card"><p className="eyebrow">Gráfico automático</p><h2>Visão dos registros</h2>{scored.length?<div className="bars">{scored.map((x,i)=><div className="bar-row" key={i}><span>{x.label}</span><div><i style={{width:`${x.score*10}%`}}/></div><strong>{x.score}</strong></div>)}</div>:<div className="chart-empty"><span>◔</span><p>O gráfico aparecerá quando houver registros com escalas de 0 a 10.</p></div>}<small>Média das escalas preenchidas em cada registro. O gráfico ajuda a visualizar tendências e não representa diagnóstico.</small></section></div>}
    {tab==="consulta"&&<div className="consult-layout"><section className="consult-hero"><p className="eyebrow">Preparar a consulta</p><h2>O que é mais importante<br/>conversar agora?</h2><p>Organize dúvidas, prioridades e decisões que deseja construir com sua médica.</p><div className="consult-meta"><span>Paciente<strong>{patient||"Não informado"}</strong></span><span>Próxima consulta<strong>{nextVisit?new Date(`${nextVisit}T12:00:00`).toLocaleDateString("pt-BR"):"A definir"}</strong></span></div></section><section className="paper-card consult-form"><label className="text-field">Minhas principais dúvidas<textarea rows={5} value={value.questions} onChange={e=>onChange(old=>({...old,questions:e.target.value}))}/></label><label className="text-field">O que funcionou e desejo manter<textarea rows={5} value={value.decisions} onChange={e=>onChange(old=>({...old,decisions:e.target.value}))}/></label><button className="print-button" onClick={()=>window.print()}>Imprimir resumo da consulta</button></section></div>}
  </section><footer className="notebook-footer"><span>Dra. Camila de Melo Matos · CRM-SP 198275</span><span>Salvamento automático neste dispositivo</span></footer></main>
}

function Scale({value,onChange}:{value:number;onChange:(v:number)=>void}) { return <div className="scale" aria-label="Escala de zero a dez">{Array.from({length:11},(_,i)=><button className={value===i?"selected":""} onClick={()=>onChange(i)} type="button" key={i}>{i}</button>)}</div> }

function ProgressPanel({data}:{data:DataMap}) { const points=modules.map(m=>({label:m.title.split(" ")[0],count:(data[m.id]?.entries||[]).filter(hasContent).length})).filter(x=>x.count); const max=Math.max(1,...points.map(x=>x.count)); return <section className="progress-panel"><div><p className="eyebrow">Evolução do ciclo</p><h2>Seus registros em perspectiva</h2><p>Quantidade não é meta. Este painel apenas ajuda a reconhecer quais temas estiveram mais presentes.</p></div><div className="progress-bars">{points.map(x=><div key={x.label}><span>{x.label}</span><i><b style={{width:`${x.count/max*100}%`}}/></i><strong>{x.count}</strong></div>)}</div></section> }
